func isBST(_ root: TreeNode?, min: Int? = nil, max: Int? = nil) -> Bool {
    guard let root = root else { return true }
    if let min = min, root.val <= min { return false }
    if let max = max, root.val >= max { return false }
    return isBST(root.left, min: min, max: root.val) && isBST(root.right, min: root.val, max: max)
}

let root = TreeNode(5, left: TreeNode(1), right: TreeNode(4, left: TreeNode(3), right: TreeNode(6)))
print(isBST(root))

